import { useState } from 'react';

// Tạo dữ liệu chấm công mẫu
const today = new Date();
const fakeAttendance = [
  { id: 1, name: 'Nguyễn Văn An', date: '22/05/2026', checkIn: '08:02', checkOut: '17:10', status: 'Đúng giờ' },
  { id: 2, name: 'Trần Thị Bình', date: '22/05/2026', checkIn: '08:45', checkOut: '17:00', status: 'Đi muộn' },
  { id: 3, name: 'Lê Văn Cường', date: '22/05/2026', checkIn: '--', checkOut: '--', status: 'Nghỉ phép' },
  { id: 4, name: 'Phạm Thị Dung', date: '22/05/2026', checkIn: '07:55', checkOut: '17:05', status: 'Đúng giờ' },
  { id: 5, name: 'Hoàng Văn Em', date: '22/05/2026', checkIn: '09:10', checkOut: '17:30', status: 'Đi muộn' },
];

const statusColors = {
  'Đúng giờ': { bg: '#dcfce7', color: '#16a34a' },
  'Đi muộn': { bg: '#fef9c3', color: '#a16207' },
  'Nghỉ phép': { bg: '#f3f4f6', color: '#6b7280' },
  'Vắng mặt': { bg: '#fef2f2', color: '#dc2626' },
};

function Attendance() {
  const [selectedDate, setSelectedDate] = useState('22/05/2026');

  return (
    <div>
      <h4 style={{ marginBottom: '4px', color: '#111' }}>Chấm công</h4>
      <p style={{ color: '#888', fontSize: '14px', marginBottom: '20px' }}>
        Theo dõi thời gian ra vào của nhân viên.
      </p>

      {/* Lọc ngày */}
      <div style={{ marginBottom: '16px', display: 'flex', alignItems: 'center', gap: '10px' }}>
        <label style={{ fontSize: '14px', color: '#555' }}>Ngày:</label>
        <input
          type="text"
          value={selectedDate}
          onChange={(e) => setSelectedDate(e.target.value)}
          style={{
            padding: '6px 10px',
            border: '1px solid #ccc',
            borderRadius: '4px',
            fontSize: '14px',
            width: '130px'
          }}
        />
      </div>

      {/* Bảng chấm công */}
      <div style={{
        backgroundColor: '#fff',
        border: '1px solid #ddd',
        borderRadius: '8px',
        overflow: 'hidden'
      }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '14px' }}>
          <thead>
            <tr style={{ backgroundColor: '#f8f9fa', borderBottom: '1px solid #ddd' }}>
              <th style={{ padding: '12px 16px', textAlign: 'left', color: '#555' }}>STT</th>
              <th style={{ padding: '12px 16px', textAlign: 'left', color: '#555' }}>Họ tên</th>
              <th style={{ padding: '12px 16px', textAlign: 'left', color: '#555' }}>Ngày</th>
              <th style={{ padding: '12px 16px', textAlign: 'left', color: '#555' }}>Giờ vào</th>
              <th style={{ padding: '12px 16px', textAlign: 'left', color: '#555' }}>Giờ ra</th>
              <th style={{ padding: '12px 16px', textAlign: 'left', color: '#555' }}>Trạng thái</th>
            </tr>
          </thead>
          <tbody>
            {fakeAttendance.map((row, index) => {
              const sc = statusColors[row.status] || { bg: '#f3f4f6', color: '#333' };
              return (
                <tr key={row.id} style={{ borderBottom: '1px solid #f0f0f0' }}>
                  <td style={{ padding: '12px 16px', color: '#888' }}>{index + 1}</td>
                  <td style={{ padding: '12px 16px', color: '#222' }}>{row.name}</td>
                  <td style={{ padding: '12px 16px', color: '#555' }}>{row.date}</td>
                  <td style={{ padding: '12px 16px', color: '#555' }}>{row.checkIn}</td>
                  <td style={{ padding: '12px 16px', color: '#555' }}>{row.checkOut}</td>
                  <td style={{ padding: '12px 16px' }}>
                    <span style={{
                      padding: '2px 8px',
                      borderRadius: '12px',
                      fontSize: '12px',
                      backgroundColor: sc.bg,
                      color: sc.color
                    }}>
                      {row.status}
                    </span>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}

export default Attendance;
